<?php $pageTitle='My reservations'; $accountActive='bookings'; require __DIR__.'/partials/header.php'; ?><main id="main" class="shell"><header class="page-heading"><p class="eyebrow">Your NepalStay</p><h1>Good things to look forward to.</h1><p>Reservations made while signed in, with the details you need close at hand.</p></header><div class="account-layout"><?php require __DIR__.'/partials/account-nav.php'; ?><section class="account-content" aria-label="Your reservations"><?php if(empty($bookings)): ?><div class="empty-state"><?= ns_icon('calendar') ?><h2>Your next stay starts here.</h2><p>You have no reservations linked to this account yet. Find a room and make a little time for yourself.</p><a class="button" href="/rooms">Explore the rooms <?= ns_icon('arrow') ?></a></div><?php else: foreach($bookings as $booking): ?><article class="history-card"><div class="history-card-top"><div><p class="label">Booking #<?= (int)$booking['id'] ?></p><h2><?= ns_e($booking['room_title']) ?></h2></div><span class="status <?= ns_status($booking['status']) ?>"><?= ns_e(ucfirst($booking['status'])) ?></span></div><div class="history-details"><div><span>Check-in</span><strong><?= ns_e(ns_date($booking['check_in'])) ?></strong></div><div><span>Check-out</span><strong><?= ns_e(ns_date($booking['check_out'])) ?></strong></div><div><span>Guests</span><strong><?= (int)$booking['num_guests'] ?></strong></div><div><span>Room total</span><strong>NPR <?= ns_money($booking['total_price']) ?></strong></div></div></article><?php endforeach; ?><div class="info-note"><strong>About your status</strong>Pending reservations are awaiting confirmation. A reservation total does not indicate payment has been received.</div><?php endif; ?></section></div></main><?php require __DIR__.'/partials/footer.php'; ?>